/**
 * IndexNow submission script.
 *
 * Reads the built sitemap (dist/sitemap-index.xml -> dist/sitemap-0.xml, generated by
 * @astrojs/sitemap during `pnpm build`) and submits the URL list to IndexNow so
 * changed pages get crawled without waiting for the next scheduled crawl.
 *
 * Requires `pnpm build` to have run first.
 *
 * Usage:
 *   node scripts/submit-indexnow.mjs        # Submit the sitemap URL list to IndexNow
 *   node scripts/submit-indexnow.mjs --dry  # Preview the URL list without submitting
 */

import { readFile } from 'node:fs/promises';
import path from 'node:path';

const DIST_DIR = path.join(process.cwd(), 'dist');
const KEY = '8zd9v9jjfedgc1ayja1z88duwuu8d8b8';
const HOST = 'dan.io.kr';
const KEY_LOCATION = `https://${HOST}/${KEY}.txt`;
const INDEXNOW_ENDPOINT = 'https://api.indexnow.org/indexnow';

function extractLocs(xml) {
  return [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map((match) => match[1]);
}

async function getSitemapUrls() {
  const indexXml = await readFile(path.join(DIST_DIR, 'sitemap-index.xml'), 'utf-8');
  const sitemapFiles = extractLocs(indexXml);

  const urls = [];
  for (const sitemapUrl of sitemapFiles) {
    const filename = new URL(sitemapUrl).pathname.split('/').pop();
    const xml = await readFile(path.join(DIST_DIR, filename), 'utf-8');
    urls.push(...extractLocs(xml));
  }

  return urls;
}

async function main() {
  const isDry = process.argv.includes('--dry');

  const urlList = await getSitemapUrls();

  if (urlList.length === 0) {
    console.error('No URLs found in dist/sitemap-index.xml. Did you run `pnpm build` first?');
    process.exitCode = 1;
    return;
  }

  console.log(`Found ${urlList.length} URL(s) in sitemap:`);
  for (const url of urlList) console.log(`  ${url}`);

  if (isDry) {
    console.log('\n--dry: not submitting to IndexNow.');
    return;
  }

  const response = await fetch(INDEXNOW_ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    body: JSON.stringify({ host: HOST, key: KEY, keyLocation: KEY_LOCATION, urlList }),
  });

  if (!response.ok) {
    console.error(`IndexNow submission failed: ${response.status} ${response.statusText}`);
    process.exitCode = 1;
    return;
  }

  console.log(`IndexNow submission succeeded (${response.status}).`);
}

main();
